start=s.index('LD73 capacity=1;');end=s.index('Vector center',start);s=s[:start]+'bool equal_abs=true;for(int j=1;j<d/2;++j)equal_abs=equal_abs&&(std::abs(squeezing[j])==std::abs(squeezing[0]));int active_rank=std::min(d/2,equal_abs?retained+1:std::max(2*retained,retained+1));capacity76(active_rank,retained+1);'+s[end:]
